// Turn MailMint's signals into one decision, and keep the reasons.
//
// Nothing here is invented: every input is something MailMint reports and a
// human could check by hand — the per-field confidence, the verbatim evidence
// span, and the SPF/DKIM/DMARC verdicts on the message as it was received.
const policy = $('Set your approval policy').first().json;
const out = [];

for (const item of $input.all()) {
  const inv = item.json;
  const conf = inv._confidence || {};
  const meta = inv._meta || {};
  const reasons = [];

  // 1. The weakest field decides. An invoice is only as trustworthy as the
  //    least certain number on it.
  const scores = Object.values(conf)
    .map((f) => (f && typeof f.confidence === 'number' ? f.confidence : null))
    .filter((n) => n !== null);
  const lowest = scores.length ? Math.min(...scores) : 0;
  if (!scores.length) reasons.push('no confidence was reported for any field');
  if (lowest < policy.min_confidence) {
    const weakest = Object.entries(conf)
      .filter(([, f]) => f && f.confidence === lowest)
      .map(([name]) => name);
    reasons.push(`confidence ${lowest} is below ${policy.min_confidence} (${weakest.join(', ')})`);
  }

  // 2. A value with no evidence was not read out of the message.
  const unevidenced = Object.entries(conf)
    .filter(([, f]) => f && !f.evidence)
    .map(([name]) => name);
  if (unevidenced.length) reasons.push(`no evidence span for ${unevidenced.join(', ')}`);

  // 3. Required values must actually be there.
  const missing = ['invoice_number', 'amount_due', 'due_date']
    .filter((k) => inv[k] === null || inv[k] === undefined || inv[k] === '');
  if (missing.length) reasons.push(`missing ${missing.join(', ')}`);

  // 4. Sender authentication. `none` means it could not be evaluated, which is
  //    not the same as a failure — both are reported as they are.
  const auth = { spf: meta.spf, dkim: meta.dkim, dmarc: meta.dmarc };
  const authenticated = auth.spf === 'pass' || auth.dkim === 'pass' || auth.dmarc === 'pass';
  if (policy.require_sender_auth && !authenticated) {
    reasons.push(`sender not authenticated (spf ${auth.spf ?? 'none'}, dkim ${auth.dkim ?? 'none'}, dmarc ${auth.dmarc ?? 'none'})`);
  }

  // 5. Money and time, computed rather than trusted.
  // Number(null) is 0, and an invoice with no amount is not an invoice for
  // nothing — a missing value has to stay missing all the way to the answer.
  const raw = inv.amount_due;
  const hasAmount = raw !== null && raw !== undefined && raw !== '';
  const amount = hasAmount ? Number(raw) : null;
  if (hasAmount && !Number.isFinite(amount)) reasons.push(`amount ${raw} is not a number`);
  if (amount !== null && Number.isFinite(amount) && amount > policy.auto_approve_up_to) {
    reasons.push(`${amount} is above the ${policy.auto_approve_up_to} ceiling`);
  }
  if (inv.currency && policy.expected_currency && inv.currency !== policy.expected_currency) {
    reasons.push(`currency ${inv.currency} is not ${policy.expected_currency}`);
  }
  let daysUntilDue = null;
  if (inv.due_date) {
    const due = new Date(inv.due_date);
    if (!Number.isNaN(due.valueOf())) {
      daysUntilDue = Math.round((due - new Date($now.toISO())) / 86400000);
      if (daysUntilDue < 0) reasons.push(`already overdue by ${Math.abs(daysUntilDue)} days`);
    }
  }

  out.push({
    json: {
      decision: reasons.length ? 'review' : 'approved',
      reasons,
      lowest_confidence: scores.length ? lowest : null,
      days_until_due: daysUntilDue,
      sender_authenticated: authenticated,
      invoice: {
        invoice_number: inv.invoice_number ?? null,
        amount_due: amount !== null && Number.isFinite(amount) ? amount : null,
        currency: inv.currency ?? null,
        due_date: inv.due_date ?? null,
        iban: inv.iban ?? null,
      },
      evidence: conf,
      auth,
      parsed_by: meta.model ?? null,
      request_id: meta.request_id ?? null,
    },
    pairedItem: item.pairedItem,
  });
}

return out;
